//! F3G-G3 (M-ito): the pile force of Ito and Matsui (1975), contract F5.10 (E15i).
//!
//! The 28 rows of X22 (`docs/fase3/exploracion/X22_filas/`) are migrated to the final format of E15i-1 in
//! `tests/data/f3g3/rows/`, with the oracle figures (cSlope 0.1.0, fixed circle, 50 slices) in
//! `tests/data/f3g3/expected.json` (generated by `tests/data/f3g3/generate.py`).
//!
//! Criteria of E15i-9: the rows within 0.1 % of the oracle, S06 in Bishop, neutrality, the mirror S05/V013c, the
//! global equilibrium (independent of the solver), the monotonicity of the force with S/D and the format rules.

use ogs_core::model::{MethodKind, Model};
use ogs_core::report::{AnalysisReport, MethodReport};
use ogs_core::{OgsError, analyze};
use serde_json::{Value, json};
use std::collections::BTreeMap;
use std::path::PathBuf;

const TOLERANCE_PCT: f64 = 0.1;
const METHODS: [&str; 5] = [
    "bishop",
    "spencer",
    "morgenstern_price",
    "janbu_simplified",
    "janbu_corrected",
];

fn data_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/data/f3g3")
}

fn expected() -> Value {
    let text = std::fs::read_to_string(data_dir().join("expected.json")).expect("expected.json");
    serde_json::from_str(&text).expect("expected.json parses")
}

fn row_doc(id: &str) -> Value {
    let text = std::fs::read_to_string(data_dir().join("rows").join(format!("{id}.json")))
        .unwrap_or_else(|e| panic!("{id}: {e}"));
    serde_json::from_str(&text).expect("row parses")
}

fn row_ids() -> Vec<String> {
    expected()["rows"].as_object().unwrap().keys().cloned().collect()
}

fn try_run(doc: &Value) -> Result<AnalysisReport, String> {
    let model: Model = serde_json::from_value(doc.clone()).map_err(|e| e.to_string())?;
    analyze(&model).map_err(|e: OgsError| e.to_string())
}

fn run(doc: &Value) -> AnalysisReport {
    try_run(doc).unwrap_or_else(|e| panic!("the analysis failed: {e}"))
}

fn method_name(m: MethodKind) -> String {
    serde_json::to_value(m).unwrap().as_str().unwrap().to_string()
}

fn fos_of(report: &AnalysisReport) -> BTreeMap<String, Option<f64>> {
    report
        .results
        .iter()
        .map(|r| (method_name(r.method), r.fos))
        .collect()
}

fn result<'a>(report: &'a AnalysisReport, method: &str) -> &'a MethodReport {
    report
        .results
        .iter()
        .find(|r| method_name(r.method) == method)
        .unwrap_or_else(|| panic!("no {method}"))
}

/// The forces of the reinforcements of one method, as JSON (the fields of E15i-7 are read by name).
fn forces(r: &MethodReport) -> Vec<Value> {
    r.reinforcement_forces
        .iter()
        .map(|f| serde_json::to_value(f).unwrap())
        .collect()
}

fn pile_mut(doc: &mut Value) -> &mut Value {
    &mut doc["reinforcements"][0]
}

fn pct(got: f64, want: f64) -> f64 {
    (got / want - 1.0) * 100.0
}

// ------------------------------------------------------------------------------------------------ data integrity

#[test]
fn the_rows_are_the_28_migrated_x22_rows() {
    let ids = row_ids();
    assert_eq!(ids.len(), 28);
    for id in &ids {
        let doc = row_doc(id);
        assert_eq!(doc["version"], "0.5", "{id}");
        let _: Model = serde_json::from_value(doc.clone()).unwrap_or_else(|e| panic!("{id}: {e}"));
        for p in doc["reinforcements"].as_array().into_iter().flatten() {
            // exactly one of `force` and `lateral_pressure` (E15i-1), and `location` is mandatory
            assert!(p.get("force").is_some() ^ p.get("lateral_pressure").is_some(), "{id}");
            if let Some(lp) = p.get("lateral_pressure") {
                assert!(matches!(lp["location"].as_str(), Some("centroid" | "slip_surface")), "{id}");
            }
        }
        assert_eq!(expected()["rows"][id]["oracle"].as_object().unwrap().len(), 5, "{id}");
    }
}

// ------------------------------------------------------------------------------------------- the oracle rows

/// `(row, method, % difference)` of the five methods of a row.
fn row_diffs(id: &str) -> Result<Vec<(String, f64)>, String> {
    let exp = expected();
    let report = try_run(&row_doc(id))?;
    let got = fos_of(&report);
    let mut out = Vec::new();
    for m in METHODS {
        let oracle = exp["rows"][id]["oracle"][m].as_f64().unwrap();
        let fos = got
            .get(m)
            .copied()
            .flatten()
            .ok_or_else(|| format!("{id}: {m} has no FS"))?;
        out.push((m.to_string(), pct(fos, oracle)));
    }
    Ok(out)
}

#[test]
fn x22_rows_match_the_oracle_within_0_1_percent() {
    let mut text = String::new();
    let mut failing = 0;
    let mut worst = (0.0_f64, String::new());
    for id in row_ids() {
        match row_diffs(&id) {
            Ok(diffs) => {
                let (m, d) = diffs
                    .iter()
                    .max_by(|a, b| a.1.abs().total_cmp(&b.1.abs()))
                    .unwrap();
                if d.abs() > TOLERANCE_PCT {
                    failing += 1;
                }
                if d.abs() > worst.0 {
                    worst = (d.abs(), id.clone());
                }
                text.push_str(&format!("  {id:<30} {d:+.4} % ({m})\n"));
            }
            Err(e) => {
                failing += 1;
                text.push_str(&format!("  {id:<30} ERROR {}\n", e.chars().take(100).collect::<String>()));
            }
        }
    }
    println!("{text}worst: {:.4} % ({})", worst.0, worst.1);
    assert!(failing == 0, "{failing} of 28 rows fail\n{text}");
}

#[test]
fn the_force_per_metre_of_the_crossing_follows_the_oracle() {
    // The oracle takes the crossing on the chord of the slice, the engine on the arc: up to 0.08 % (X22 §5.2).
    let exp = expected();
    let mut checked = 0;
    for id in row_ids() {
        let Some(f) = exp["rows"][&id].get("force_per_metre") else { continue };
        let report = run(&row_doc(&id));
        let r = result(&report, "bishop");
        let fs = forces(r);
        match f["estado"].as_str().unwrap() {
            "outside_mass" => {
                assert!(fs.iter().all(|x| x["status"] != "applied"), "{id}");
            }
            _ => {
                assert_eq!(fs.len(), 1, "{id}");
                let got = fs[0]["available"].as_f64().unwrap();
                let want = f["oracle"].as_f64().unwrap();
                assert!(pct(got, want).abs() <= TOLERANCE_PCT, "{id}: {got} against {want}");
                if let Some(g) = f["gobierna"].as_str().filter(|g| *g != "given") {
                    let name = match g {
                        "bending" => "bending",
                        other => other,
                    };
                    assert_eq!(fs[0]["governs"], name, "{id}");
                }
                checked += 1;
            }
        }
    }
    assert!(checked >= 20, "{checked}");
}

#[test]
fn s06_converges_in_bishop() {
    // D1/D = 0.25: the soil force is 5150 kN/m and FS ≈ 11.6; the fixed point of E14o-2 used to end at 0.
    let exp = expected();
    let report = run(&row_doc("X22-S06-D1D-pequeno"));
    let r = result(&report, "bishop");
    assert_eq!(r.status, ogs_core::methods::SolveStatus::Converged, "{:?}", r.warnings);
    let want = exp["rows"]["X22-S06-D1D-pequeno"]["oracle"]["bishop"].as_f64().unwrap();
    let d = pct(r.fos.unwrap(), want);
    println!("S06 Bishop: {:.6} against {want} ({d:+.4} %)", r.fos.unwrap());
    assert!(d.abs() <= TOLERANCE_PCT, "{d}");
}

// ------------------------------------------------------------------------------------------------- neutrality

#[test]
fn without_lateral_pressure_the_report_has_no_new_field() {
    // E15i-7: `soil_force`, `governs` and `arm` are omitted in a pile with `force` (identity).
    for id in ["X22-G01-force-pasivo", "X22-G02-force-activo", "X22-G03-force-tangente"] {
        let report = run(&row_doc(id));
        let text = serde_json::to_string(&report).unwrap();
        for key in ["soil_force", "governs", "\"arm\""] {
            assert!(!text.contains(key), "{id}: {key}");
        }
        assert!(!forces(result(&report, "bishop")).is_empty(), "{id}");
    }
}

#[test]
fn n01_and_n02_give_the_fs_without_pile() {
    let n01 = fos_of(&run(&row_doc("X22-N01-sin-pilote")));
    let n02 = fos_of(&run(&row_doc("X22-N02-fuera")));
    let b = fos_of(&run(&row_doc("X22-V013b")));
    for m in METHODS {
        assert_eq!(n01[m], n02[m], "{m}: N02 is the slope without pile");
        // V013b: the critical circle of cSlope ends at the head of the pile; the crossing at the end does not count
        let want = expected()["rows"]["X22-V013b"]["oracle"][m].as_f64().unwrap();
        assert!(pct(b[m].unwrap(), want).abs() <= TOLERANCE_PCT, "{m}");
    }
    let rep = run(&row_doc("X22-N02-fuera"));
    assert!(forces(result(&rep, "bishop")).iter().all(|f| f["status"] != "applied"));
}

#[test]
fn a_pile_without_a_crossing_changes_nothing() {
    // The same model with the pile moved off the sliding mass is the model without the pile, bit for bit.
    let mut doc = row_doc("X22-V013c");
    let base = {
        let mut d = doc.clone();
        d.as_object_mut().unwrap().remove("reinforcements");
        run(&d)
    };
    pile_mut(&mut doc)["x1"] = json!(31.0);
    pile_mut(&mut doc)["x2"] = json!(31.0);
    let moved = run(&doc);
    for m in METHODS {
        assert_eq!(fos_of(&base)[m], fos_of(&moved)[m], "{m}");
    }
}

// ----------------------------------------------------------------------------------------------------- mirror

#[test]
fn the_mirror_s05_matches_v013c_within_1e_9() {
    let a = fos_of(&run(&row_doc("X22-V013c")));
    let b = fos_of(&run(&row_doc("X22-S05-espejo")));
    let mut worst = 0.0_f64;
    for m in METHODS {
        let d = (a[m].unwrap() - b[m].unwrap()).abs();
        worst = worst.max(d);
        assert!(d <= 1e-9, "{m}: {d:e}");
    }
    println!("mirror: worst |Δ| = {worst:e}");
}

// ------------------------------------------------------------------------------------- the format rules (E15i-1)

fn reject(doc: &Value) -> String {
    match try_run(doc) {
        Ok(_) => panic!("the document should be rejected"),
        Err(e) => e,
    }
}

#[test]
fn the_format_rules_of_e15i_1() {
    let base = row_doc("X22-V013c");
    let with = |f: &dyn Fn(&mut Value)| {
        let mut d = base.clone();
        f(pile_mut(&mut d));
        d
    };
    let cases: Vec<(&str, Value, Vec<&str>)> = vec![
        (
            "force and lateral_pressure",
            with(&|p| p["force"] = json!(100.0)),
            vec!["InvalidModel", "reinforcements[0]", "force", "lateral_pressure"],
        ),
        (
            "neither",
            with(&|p| {
                p.as_object_mut().unwrap().remove("lateral_pressure");
            }),
            vec!["InvalidModel", "reinforcements[0]", "force", "lateral_pressure"],
        ),
        (
            "unknown model",
            with(&|p| p["lateral_pressure"]["model"] = json!("broms")),
            vec!["reinforcements[0].lateral_pressure.model"],
        ),
        (
            "diameter 0",
            with(&|p| p["lateral_pressure"]["diameter"] = json!(0.0)),
            vec!["reinforcements[0].lateral_pressure.diameter"],
        ),
        (
            "diameter negative",
            with(&|p| p["lateral_pressure"]["diameter"] = json!(-0.8)),
            vec!["reinforcements[0].lateral_pressure.diameter"],
        ),
        (
            "location missing",
            with(&|p| {
                p["lateral_pressure"].as_object_mut().unwrap().remove("location");
            }),
            vec!["location"],
        ),
        (
            "location bottom",
            with(&|p| p["lateral_pressure"]["location"] = json!("bottom")),
            vec!["location"],
        ),
        (
            "location with a hyphen",
            with(&|p| p["lateral_pressure"]["location"] = json!("slip-surface")),
            vec!["location"],
        ),
        (
            "unknown field in lateral_pressure",
            with(&|p| p["lateral_pressure"]["friction"] = json!(0.3)),
            vec!["friction"],
        ),
        (
            "inclined pile",
            with(&|p| p["x2"] = json!(18.5)),
            vec!["InvalidModel", "reinforcements[0].x2", "vertical"],
        ),
        (
            "spacing equal to the diameter",
            with(&|p| p["spacing"] = json!(0.8)),
            vec!["InvalidModel", "reinforcements[0].spacing", "diameter"],
        ),
        (
            "spacing below the diameter",
            with(&|p| p["spacing"] = json!(0.5)),
            vec!["reinforcements[0].spacing"],
        ),
        (
            "empty capacity",
            with(&|p| p["capacity"] = json!({})),
            vec!["reinforcements[0].capacity"],
        ),
        (
            "capacity shear 0",
            with(&|p| p["capacity"] = json!({"shear": 0.0})),
            vec!["reinforcements[0].capacity.shear"],
        ),
        (
            "capacity moment negative",
            with(&|p| p["capacity"] = json!({"moment": -1.0})),
            vec!["reinforcements[0].capacity.moment"],
        ),
        (
            "unknown field in capacity",
            with(&|p| p["capacity"] = json!({"shear": 10.0, "axial": 3.0})),
            vec!["axial"],
        ),
        (
            "capacity with force",
            with(&|p| {
                p.as_object_mut().unwrap().remove("lateral_pressure");
                p["force"] = json!(100.0);
                p["capacity"] = json!({"shear": 10.0});
            }),
            vec!["InvalidModel", "reinforcements[0].capacity"],
        ),
        (
            "angle forbidden with tangent still applies",
            with(&|p| p["direction"] = json!("tangent")),
            vec!["reinforcements[0].angle"],
        ),
    ];
    for (name, doc, needles) in cases {
        let err = reject(&doc);
        for n in &needles {
            assert!(err.contains(n), "{name}: `{err}` lacks `{n}`");
        }
    }
}

#[test]
fn the_version_gate_of_e15i_1() {
    for old in ["0.1", "0.2", "0.3", "0.4"] {
        for strip_lp in [false, true] {
            let mut doc = row_doc("X22-V013c");
            doc["version"] = json!(old);
            if old == "0.1" {
                doc["loads"] = json!([]);
            }
            if strip_lp {
                // `capacity` alone also needs 0.5 (it is rejected for another reason with `force`, after the gate)
                let p = pile_mut(&mut doc);
                p.as_object_mut().unwrap().remove("lateral_pressure");
                p["force"] = json!(100.0);
                p["capacity"] = json!({"shear": 10.0});
            }
            let err = reject(&doc);
            if old == "0.4" || old == "0.3" || old == "0.2" || old == "0.1" {
                assert!(
                    err.contains("requiere version \"0.5\"") || err.contains("requiere version \"0.4\""),
                    "{old}: {err}"
                );
            }
            if old == "0.4" {
                assert!(err.contains("lateral_pressure requiere version \"0.5\""), "{old}: {err}");
            }
        }
    }
}

#[test]
fn a_v0_4_pile_with_force_keeps_working() {
    let mut doc = row_doc("X22-G01-force-pasivo");
    doc["version"] = json!("0.4");
    let r = run(&doc);
    assert!(result(&r, "bishop").fos.is_some());
}

// ------------------------------------------------------------------------------- output, point of application

#[test]
fn the_output_of_a_pile_with_lateral_pressure() {
    let report = run(&row_doc("X22-V013c"));
    let r = result(&report, "bishop");
    let f = &forces(r)[0];
    // X22 §3: L_m = 1.2235; the force per pile 282.9 kN, 117.85 kN/m for a spacing of 2.4 m
    let arm = f["arm"].as_f64().unwrap();
    assert!((arm - 1.2235).abs() < 2e-3, "{arm}");
    let soil = f["soil_force"].as_f64().unwrap();
    assert!((soil - 117.85).abs() < 0.12, "{soil}");
    assert_eq!(f["governs"], "soil");
    assert_eq!(f["available"].as_f64().unwrap(), soil, "nothing caps it");
    assert_eq!(f["application"], "passive");
    assert_eq!(f["status"], "applied");
    // the force is horizontal: `angle` 0, against the movement (the slope goes to -x)
    assert!(f["fy"].as_f64().unwrap().abs() < 1e-12);
    assert!(f["fx"].as_f64().unwrap() > 0.0);
}

#[test]
fn the_capacity_is_a_minimum_and_says_what_governs() {
    let shear = run(&row_doc("X22-S11-capacidad-corte"));
    let f = forces(result(&shear, "bishop"))[0].clone();
    assert_eq!(f["governs"], "shear");
    assert!((f["available"].as_f64().unwrap() - 150.0 / 2.4).abs() < 1e-12);
    assert!(f["soil_force"].as_f64().unwrap() > f["available"].as_f64().unwrap());

    let moment = run(&row_doc("X22-S12-capacidad-momento"));
    let f = forces(result(&moment, "bishop"))[0].clone();
    assert_eq!(f["governs"], "bending");
    let arm = f["arm"].as_f64().unwrap();
    assert!((f["available"].as_f64().unwrap() - 250.0 / arm / 2.4).abs() < 1e-9);

    // a capacity above the soil force does not change anything
    let mut doc = row_doc("X22-V013c");
    pile_mut(&mut doc)["capacity"] = json!({"shear": 1.0e6, "moment": 1.0e9});
    let big = run(&doc);
    let plain = run(&row_doc("X22-V013c"));
    assert_eq!(fos_of(&big), fos_of(&plain));
    assert_eq!(forces(result(&big, "bishop"))[0]["governs"], "soil");
}

#[test]
fn the_point_of_application_changes_the_fs_with_moments_only() {
    // X22 §3: same circle, centroid against slip_surface. Bishop and Spencer move ~1 %; Janbu does not (no moments).
    let c = fos_of(&run(&row_doc("X22-V013c")));
    let s = fos_of(&run(&row_doc("X22-L01-xs-mismo-circulo")));
    assert!(s["bishop"].unwrap() > c["bishop"].unwrap() * 1.005);
    assert!(s["spencer"].unwrap() > c["spencer"].unwrap() * 1.005);
    assert_eq!(s["janbu_simplified"], c["janbu_simplified"]);
    assert_eq!(s["janbu_corrected"], c["janbu_corrected"]);
    let c_arm = forces(result(&run(&row_doc("X22-V013c")), "bishop"))[0]["arm"].clone();
    let s_arm = forces(result(&run(&row_doc("X22-L01-xs-mismo-circulo")), "bishop"))[0]["arm"].clone();
    assert_eq!(c_arm, s_arm, "`arm` is L_m in both; only the point of the force changes");
}

// ----------------------------------------------------------------------------------------------- the warning

#[test]
fn the_spacing_range_warning() {
    let code = "ito_matsui_spacing_range";
    let has = |id: &str| {
        let r = run(&row_doc(id));
        // every method of the report carries it, or none does
        let n = r.results.iter().filter(|m| m.warnings.iter().any(|w| w == code)).count();
        assert!(n == 0 || n == r.results.len(), "{id}: {n} of {}", r.results.len());
        n > 0
    };
    assert!(has("X22-S06-D1D-pequeno"), "S/D = 1.25 < 2");
    assert!(has("X22-S07-D1D-grande"), "S/D = 10 > 8");
    assert!(has("X22-S15-piso-phi0"), "S/D = 20 > 8");
    for id in ["X22-V013b", "X22-V013c", "X22-V013d", "X22-V013e", "X22-S01-phi0", "X22-N01-sin-pilote"] {
        assert!(!has(id), "{id}: S/D within 2 to 8");
    }
    // the boundaries are inside the range: S/D = 2 and S/D = 8 give no warning
    for sd in [2.0, 8.0] {
        let mut doc = row_doc("X22-V013c");
        pile_mut(&mut doc)["spacing"] = json!(0.8 * sd);
        let r = run(&doc);
        assert!(!result(&r, "bishop").warnings.iter().any(|w| w == code), "S/D = {sd}");
    }
}

// -------------------------------------------------------------------------------------------- monotonicity

#[test]
fn the_force_decreases_with_the_spacing() {
    // E15i-9: the force per pile and per metre decrease with S/D (material of V013, d = 0.8, same circle).
    let mut last: Option<(f64, f64)> = None;
    for sd in [1.5, 2.0, 3.0, 4.0, 6.0, 8.0, 12.0] {
        let mut doc = row_doc("X22-V013c");
        pile_mut(&mut doc)["spacing"] = json!(0.8 * sd);
        let r = run(&doc);
        let f = forces(result(&r, "bishop"))[0].clone();
        let per_metre = f["soil_force"].as_f64().unwrap();
        let per_pile = per_metre * 0.8 * sd;
        if let Some((pp, pm)) = last {
            assert!(per_pile < pp, "S/D = {sd}: {per_pile} !< {pp}");
            assert!(per_metre < pm, "S/D = {sd}: {per_metre} !< {pm}");
        }
        last = Some((per_pile, per_metre));
    }
}

#[test]
fn the_fs_does_not_fall_when_phi_rises_at_a_large_spacing() {
    // The floor of φ = 0 (E15i-2, S/D ≥ 8): the force never drops when φ grows from 0.
    let mut last = 0.0_f64;
    for phi in [0.0, 1.0, 2.0, 5.0, 10.0, 15.0] {
        let mut doc = row_doc("X22-S15-piso-phi0");
        doc["materials"][0]["friction_angle"] = json!(phi);
        let r = run(&doc);
        let f = forces(result(&r, "bishop")).first().cloned();
        let soil = f.map_or(0.0, |f| f["soil_force"].as_f64().unwrap());
        assert!(soil >= last - 1e-12, "phi = {phi}: {soil} < {last}");
        last = soil;
    }
}

// --------------------------------------------------------------------------- independent global equilibrium

/// Forces on the sliding mass (point, force) from the report, **as physics**: the weights at the midpoint of each
/// slice, the forces of the piles at their application point (`y + arm` with `centroid`, the crossing with
/// `slip_surface`), passive ones divided by `F`; and the base forces from the closed form of the slice.
struct Balance {
    force: [f64; 2],
    force_scale: f64,
    moment: [f64; 2],
    moment_scale: [f64; 2],
    e_n: f64,
    total_w: f64,
}

fn pile_loads(doc: &Value, r: &MethodReport, f: f64) -> Vec<([f64; 2], [f64; 2])> {
    let mut out = Vec::new();
    for rf in forces(r) {
        if rf["status"] != "applied" {
            continue;
        }
        let id = rf["id"].as_str().unwrap();
        let spec = doc["reinforcements"]
            .as_array()
            .unwrap()
            .iter()
            .find(|p| p["id"] == id)
            .unwrap();
        let at_centroid = spec["lateral_pressure"]["location"] == "centroid";
        let arm = rf.get("arm").and_then(Value::as_f64).unwrap_or(0.0);
        let (x, y) = (rf["x"].as_f64().unwrap(), rf["y"].as_f64().unwrap());
        let y_app = if at_centroid { y + arm } else { y };
        let k = if spec["application"] == "passive" { 1.0 / f } else { 1.0 };
        out.push(([x, y_app], [rf["fx"].as_f64().unwrap() * k, rf["fy"].as_f64().unwrap() * k]));
    }
    out
}

fn balance(doc: &Value, r: &MethodReport, s_dir: f64, about: [[f64; 2]; 2]) -> Balance {
    let (f, lambda) = (r.fos.unwrap(), r.lambda.unwrap());
    let mut loads = pile_loads(doc, r, f);
    let (mut e_n, mut total_w) = (0.0_f64, 0.0_f64);
    // the slice that takes each force: the first soil slice from the toe that holds x
    let mut w_extra = vec![0.0_f64; r.slices.len()];
    let mut h_extra = vec![0.0_f64; r.slices.len()];
    for (p, fo) in &loads {
        let k = r
            .slices
            .iter()
            .position(|q| q.weight > 0.0 && q.x_left <= p[0] && p[0] <= q.x_right)
            .expect("a soil slice holds the crossing");
        w_extra[k] += -fo[1];
        h_extra[k] += s_dir * fo[0];
    }
    for (i, s) in r.slices.iter().enumerate() {
        let (sin, cos) = s.alpha.sin_cos();
        let xm = 0.5 * (s.x_left + s.x_right);
        let ym = 0.5 * (s.y_base_left + s.y_base_right);
        let (w_star, h) = (s.weight + w_extra[i], h_extra[i]);
        total_w += s.weight;
        if s.weight > 0.0 {
            loads.push(([xm, ym], [0.0, -s.weight]));
        }
        let l = s.base_length;
        let resist = (w_star * cos - s.pore_pressure * l) * s.tan_phi + s.cohesion * l;
        let d = (sin - lambda * cos) * s.tan_phi + (cos + lambda * sin) * f;
        let de = if s.weight == 0.0 {
            0.0
        } else {
            (f * w_star * sin - resist + (f * cos + s.tan_phi * sin) * h) / d
        };
        let n_eff = w_star * cos - s.pore_pressure * l - h * sin + (sin - lambda * cos) * de;
        let shear = (s.cohesion * l + n_eff * s.tan_phi) / f;
        let normal = n_eff + s.pore_pressure * l;
        e_n += de;
        if s.weight > 0.0 {
            let n_vec = [s_dir * sin, cos];
            let m = [s_dir * cos, -sin];
            loads.push((
                [xm, ym],
                [normal * n_vec[0] - shear * m[0], normal * n_vec[1] - shear * m[1]],
            ));
        }
    }
    let force = [
        loads.iter().map(|l| l.1[0]).sum::<f64>(),
        loads.iter().map(|l| l.1[1]).sum::<f64>(),
    ];
    let force_scale = loads.iter().map(|l| l.1[0].hypot(l.1[1])).sum::<f64>();
    let moment_about = |o: [f64; 2]| -> (f64, f64) {
        let terms: Vec<f64> = loads
            .iter()
            .map(|(p, fo)| (p[0] - o[0]) * fo[1] - (p[1] - o[1]) * fo[0])
            .collect();
        (terms.iter().sum(), terms.iter().map(|t| t.abs()).sum())
    };
    let (m0, s0) = moment_about(about[0]);
    let (m1, s1) = moment_about(about[1]);
    Balance {
        force,
        force_scale,
        moment: [m0, m1],
        moment_scale: [s0, s1],
        e_n,
        total_w,
    }
}

#[test]
fn global_equilibrium_independent_of_the_solver() {
    // Spencer and Morgenstern-Price (constant): E_n = 0, ΣFx = ΣFy = 0 and the moment about two points = 0 with the
    // pile at its application point and the passive force divided by F.
    let mut worst = 0.0_f64;
    for id in [
        "X22-V013c",
        "X22-L01-xs-mismo-circulo",
        "X22-V013d",
        "X22-V013e-xs",
        "X22-S01-phi0",
        "X22-S03-2capas",
        "X22-S04-agua",
        "X22-S05-espejo",
        "X22-S09-activo",
        "X22-S10-tangente",
        "X22-S11-capacidad-corte",
        "X22-S12-capacidad-momento",
    ] {
        let mut doc = row_doc(id);
        doc["analysis"]["tolerance"] = json!(1e-12);
        let report = run(&doc);
        let ltr = doc["slope"]["direction"] == "left_to_right";
        let s_dir = if ltr { 1.0 } else { -1.0 };
        let c = &doc["analysis"]["surface"];
        let (cx, cy) = (c["xc"].as_f64().unwrap(), c["yc"].as_f64().unwrap());
        for m in ["spencer", "morgenstern_price"] {
            let r = result(&report, m);
            let b = balance(&doc, r, s_dir, [[cx, cy], [cx + 15.0, cy - 12.0]]);
            let res = [
                b.force[0].abs() / b.force_scale,
                b.force[1].abs() / b.force_scale,
                b.moment[0].abs() / b.moment_scale[0],
                b.moment[1].abs() / b.moment_scale[1],
            ];
            println!(
                "{id:<28} {m:<18} F={:.6} E_n/ΣW={:+.1e} ΣFx={:.1e} ΣFy={:.1e} M0={:.1e} M1={:.1e}",
                r.fos.unwrap(),
                b.e_n / b.total_w,
                res[0],
                res[1],
                res[2],
                res[3]
            );
            assert!(b.e_n.abs() <= 1e-6 * b.total_w, "{id} {m}: E_n = {:e}", b.e_n);
            for (name, v) in ["ΣFx", "ΣFy", "M0", "M1"].iter().zip(res) {
                assert!(v < 1e-6, "{id} {m}: {name} residual {v:e}");
                worst = worst.max(v);
            }
        }
    }
    println!("worst residual = {worst:.2e}");
}

#[test]
fn the_balance_detects_a_missing_pile_force() {
    // The test above discriminates: with the force of the pile left out of the balance it must fail.
    let mut doc = row_doc("X22-V013c");
    doc["analysis"]["tolerance"] = json!(1e-12);
    let report = run(&doc);
    let r = result(&report, "spencer");
    let c = &doc["analysis"]["surface"];
    let (cx, cy) = (c["xc"].as_f64().unwrap(), c["yc"].as_f64().unwrap());
    let mut no_pile = doc.clone();
    no_pile["reinforcements"][0]["application"] = json!("passive");
    // moving the application point of the force to the crossing (as `slip_surface`) breaks the moment balance
    no_pile["reinforcements"][0]["lateral_pressure"]["location"] = json!("slip_surface");
    let b = balance(&no_pile, r, -1.0, [[cx, cy], [cx + 15.0, cy - 12.0]]);
    assert!(b.moment[0].abs() / b.moment_scale[0] > 1e-5);
}
